//go:build e2e

package e2e

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"
)

// testBinaryPath holds the path to the CLI binary built once in TestMain.
// All tests share this binary to avoid repeated builds.
var testBinaryPath string

// defaultAgent holds the agent to test with, determined in TestMain.
var defaultAgent string

// TestMain builds the CLI binary once and checks agent availability before running tests.
func TestMain(m *testing.M) {
	// Determine which agent to test with
	defaultAgent = os.Getenv("E2E_AGENT")
	if defaultAgent == "" {
		defaultAgent = "claude-code"
	}

	// Check if the agent is available
	runner := NewAgentRunner(defaultAgent, AgentRunnerConfig{})
	available, err := runner.IsAvailable()
	if !available {
		fmt.Printf("Agent %s not available (%v), skipping E2E tests\n", defaultAgent, err)
		// Exit 0 to not fail CI when agent isn't configured
		os.Exit(0)
	}

	// Build binary once to a temp directory
	tmpDir, err := os.MkdirTemp("", "entire-e2e-test-*")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create temp dir for binary: %v\n", err)
		os.Exit(1)
	}

	testBinaryPath = filepath.Join(tmpDir, "entire")

	moduleRoot := findModuleRoot()
	buildCmd := exec.Command("go", "build", "-o", testBinaryPath, ".")
	buildCmd.Dir = filepath.Join(moduleRoot, "cmd", "entire")

	buildOutput, err := buildCmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to build CLI binary: %v\nOutput: %s\n", err, buildOutput)
		os.RemoveAll(tmpDir)
		os.Exit(1)
	}

	// Add binary to PATH so hooks can find it
	origPath := os.Getenv("PATH")
	os.Setenv("PATH", tmpDir+string(os.PathListSeparator)+origPath)

	// Run tests
	code := m.Run()

	// Cleanup
	os.Setenv("PATH", origPath)
	os.RemoveAll(tmpDir)
	os.Exit(code)
}

// getTestBinary returns the path to the shared test binary.
// It panics if TestMain hasn't run (testBinaryPath is empty).
func getTestBinary() string {
	if testBinaryPath == "" {
		panic("testBinaryPath not set - TestMain must run before tests")
	}
	return testBinaryPath
}

// findModuleRoot finds the Go module root by walking up from the current file.
func findModuleRoot() string {
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		panic("failed to get current file path via runtime.Caller")
	}
	dir := filepath.Dir(thisFile)

	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			panic("could not find go.mod starting from " + thisFile)
		}
		dir = parent
	}
}

//go:build e2e

package e2e

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// AgentRunner abstracts invoking a coding agent for e2e tests.
// This follows the multi-agent pattern from cmd/entire/cli/agent/agent.go.
type AgentRunner interface {
	// Name returns the agent name (e.g., "claude-code", "gemini-cli")
	Name() string

	// IsAvailable checks if the agent CLI is installed and authenticated
	IsAvailable() (bool, error)

	// RunPrompt executes a prompt and returns the result
	RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error)

	// RunPromptWithTools executes with specific allowed tools
	RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error)
}

// AgentResult holds the result of an agent invocation.
type AgentResult struct {
	Stdout   string
	Stderr   string
	ExitCode int
	Duration time.Duration
}

// AgentRunnerConfig holds configuration for agent runners.
type AgentRunnerConfig struct {
	Model   string        // Model to use (e.g., "haiku" for Claude)
	Timeout time.Duration // Timeout per prompt
}

// NewAgentRunner creates an agent runner based on the agent name.
func NewAgentRunner(name string, config AgentRunnerConfig) AgentRunner {
	switch name {
	case "claude-code":
		return NewClaudeCodeRunner(config)
	case "gemini-cli":
		return NewGeminiCLIRunner(config)
	default:
		// Return a runner that reports as unavailable
		return &unavailableRunner{name: name}
	}
}

// unavailableRunner is returned for unknown agent names.
type unavailableRunner struct {
	name string
}

func (r *unavailableRunner) Name() string { return r.name }

func (r *unavailableRunner) IsAvailable() (bool, error) {
	return false, fmt.Errorf("unknown agent: %s", r.name)
}

func (r *unavailableRunner) RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
	return nil, fmt.Errorf("agent %s is not available", r.name)
}

func (r *unavailableRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
	return nil, fmt.Errorf("agent %s is not available", r.name)
}

// ClaudeCodeRunner implements AgentRunner for Claude Code CLI.
type ClaudeCodeRunner struct {
	Model        string
	Timeout      time.Duration
	AllowedTools []string
}

// NewClaudeCodeRunner creates a new Claude Code runner with the given config.
func NewClaudeCodeRunner(config AgentRunnerConfig) *ClaudeCodeRunner {
	model := config.Model
	if model == "" {
		model = os.Getenv("E2E_CLAUDE_MODEL")
		if model == "" {
			model = "haiku"
		}
	}

	timeout := config.Timeout
	if timeout == 0 {
		if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
			if parsed, err := time.ParseDuration(envTimeout); err == nil {
				timeout = parsed
			}
		}
		if timeout == 0 {
			timeout = 2 * time.Minute
		}
	}

	return &ClaudeCodeRunner{
		Model:        model,
		Timeout:      timeout,
		AllowedTools: []string{"Edit", "Read", "Write", "Bash", "Glob", "Grep"},
	}
}

func (r *ClaudeCodeRunner) Name() string {
	return "claude-code"
}

// IsAvailable checks if Claude CLI is installed and working.
// Note: Claude Code uses OAuth authentication (via `claude login`), not ANTHROPIC_API_KEY.
func (r *ClaudeCodeRunner) IsAvailable() (bool, error) {
	// Check if claude CLI is in PATH
	if _, err := exec.LookPath("claude"); err != nil {
		return false, fmt.Errorf("claude CLI not found in PATH: %w", err)
	}

	// Check if claude is working (--version doesn't require auth)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "claude", "--version")
	if err := cmd.Run(); err != nil {
		return false, fmt.Errorf("claude CLI not working: %w", err)
	}

	return true, nil
}

func (r *ClaudeCodeRunner) RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
	return r.RunPromptWithTools(ctx, workDir, prompt, r.AllowedTools)
}

func (r *ClaudeCodeRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
	// Build command: claude --model <model> -p "<prompt>" --allowedTools <tools>
	args := []string{
		"--model", r.Model,
		"-p", prompt,
	}

	if len(tools) > 0 {
		args = append(args, "--allowedTools", strings.Join(tools, ","))
	}

	// Create context with timeout
	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "claude", args...)
	cmd.Dir = workDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	start := time.Now()
	err := cmd.Run()
	duration := time.Since(start)

	result := &AgentResult{
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		Duration: duration,
	}

	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			result.ExitCode = exitErr.ExitCode()
		} else {
			result.ExitCode = -1
		}
		return result, err
	}

	result.ExitCode = 0
	return result, nil
}

// GeminiCLIRunner implements AgentRunner for Gemini CLI.
// This is a placeholder for future implementation.
type GeminiCLIRunner struct {
	Timeout time.Duration
}

// NewGeminiCLIRunner creates a new Gemini CLI runner with the given config.
func NewGeminiCLIRunner(config AgentRunnerConfig) *GeminiCLIRunner {
	timeout := config.Timeout
	if timeout == 0 {
		timeout = 2 * time.Minute
	}

	return &GeminiCLIRunner{
		Timeout: timeout,
	}
}

func (r *GeminiCLIRunner) Name() string {
	return "gemini-cli"
}

// IsAvailable checks if Gemini CLI is installed and authenticated.
func (r *GeminiCLIRunner) IsAvailable() (bool, error) {
	// Check if gemini CLI is in PATH
	if _, err := exec.LookPath("gemini"); err != nil {
		return false, fmt.Errorf("gemini CLI not found in PATH: %w", err)
	}

	// Check if gemini is working
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "gemini", "--version")
	if err := cmd.Run(); err != nil {
		return false, fmt.Errorf("gemini CLI not working: %w", err)
	}

	return true, nil
}

func (r *GeminiCLIRunner) RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
	return r.RunPromptWithTools(ctx, workDir, prompt, nil)
}

func (r *GeminiCLIRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
	// Gemini CLI implementation would go here
	// For now, return an error indicating it's not fully implemented
	return nil, fmt.Errorf("gemini CLI runner not yet implemented")
}

//go:build e2e

package e2e

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/format/config"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// E2ETestEnv manages an isolated test environment for E2E tests with real agent calls.
type E2ETestEnv struct {
	T       *testing.T
	RepoDir string
	Agent   AgentRunner
}

// NewE2ETestEnv creates a new isolated E2E test environment.
func NewE2ETestEnv(t *testing.T) *E2ETestEnv {
	t.Helper()

	// Resolve symlinks on macOS where /var -> /private/var
	repoDir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(repoDir); err == nil {
		repoDir = resolved
	}

	// Create agent runner
	agent := NewAgentRunner(defaultAgent, AgentRunnerConfig{})

	return &E2ETestEnv{
		T:       t,
		RepoDir: repoDir,
		Agent:   agent,
	}
}

// NewE2EFeatureBranchEnv creates an E2E test environment ready for testing.
// It initializes the repo, creates an initial commit on main,
// and checks out a feature branch.
func NewE2EFeatureBranchEnv(t *testing.T, strategyName string) *E2ETestEnv {
	t.Helper()

	env := NewE2ETestEnv(t)
	env.InitRepo()
	env.InitEntire(strategyName)
	env.WriteFile("README.md", "# Test Repository\n\nThis is a test repository for E2E testing.\n")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/e2e-test")

	return env
}

// InitRepo initializes a git repository in the test environment.
func (env *E2ETestEnv) InitRepo() {
	env.T.Helper()

	repo, err := git.PlainInit(env.RepoDir, false)
	if err != nil {
		env.T.Fatalf("failed to init git repo: %v", err)
	}

	// Configure git user for commits
	cfg, err := repo.Config()
	if err != nil {
		env.T.Fatalf("failed to get repo config: %v", err)
	}
	cfg.User.Name = "E2E Test User"
	cfg.User.Email = "e2e-test@example.com"

	// Disable GPG signing for test commits
	if cfg.Raw == nil {
		cfg.Raw = config.New()
	}
	cfg.Raw.Section("commit").SetOption("gpgsign", "false")

	if err := repo.SetConfig(cfg); err != nil {
		env.T.Fatalf("failed to set repo config: %v", err)
	}
}

// InitEntire initializes the .entire directory with the specified strategy.
func (env *E2ETestEnv) InitEntire(strategyName string) {
	env.T.Helper()

	// Create .entire directory structure
	entireDir := filepath.Join(env.RepoDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		env.T.Fatalf("failed to create .entire directory: %v", err)
	}

	// Create tmp directory
	tmpDir := filepath.Join(entireDir, "tmp")
	if err := os.MkdirAll(tmpDir, 0o755); err != nil {
		env.T.Fatalf("failed to create .entire/tmp directory: %v", err)
	}

	// Write settings.json
	settings := map[string]any{
		"strategy":  strategyName,
		"local_dev": true, // Use go run for hooks in tests
	}
	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		env.T.Fatalf("failed to marshal settings: %v", err)
	}
	data = append(data, '\n')
	settingsPath := filepath.Join(entireDir, "settings.json")
	if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
		env.T.Fatalf("failed to write settings.json: %v", err)
	}
}

// WriteFile creates a file with the given content in the test repo.
func (env *E2ETestEnv) WriteFile(path, content string) {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)

	// Create parent directories
	dir := filepath.Dir(fullPath)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		env.T.Fatalf("failed to create directory %s: %v", dir, err)
	}

	if err := os.WriteFile(fullPath, []byte(content), 0o644); err != nil {
		env.T.Fatalf("failed to write file %s: %v", path, err)
	}
}

// ReadFile reads a file from the test repo.
func (env *E2ETestEnv) ReadFile(path string) string {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	data, err := os.ReadFile(fullPath)
	if err != nil {
		env.T.Fatalf("failed to read file %s: %v", path, err)
	}
	return string(data)
}

// TryReadFile reads a file from the test repo, returning empty string if not found.
func (env *E2ETestEnv) TryReadFile(path string) string {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	data, err := os.ReadFile(fullPath)
	if err != nil {
		return ""
	}
	return string(data)
}

// FileExists checks if a file exists in the test repo.
func (env *E2ETestEnv) FileExists(path string) bool {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	_, err := os.Stat(fullPath)
	return err == nil
}

// GitAdd stages files for commit.
func (env *E2ETestEnv) GitAdd(paths ...string) {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	for _, path := range paths {
		if _, err := worktree.Add(path); err != nil {
			env.T.Fatalf("failed to add file %s: %v", path, err)
		}
	}
}

// GitCommit creates a commit with all staged files.
func (env *E2ETestEnv) GitCommit(message string) {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	_, err = worktree.Commit(message, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "E2E Test User",
			Email: "e2e-test@example.com",
			When:  time.Now(),
		},
	})
	if err != nil {
		env.T.Fatalf("failed to commit: %v", err)
	}
}

// GitCommitWithShadowHooks stages and commits files, running the prepare-commit-msg
// and post-commit hooks like a real workflow.
func (env *E2ETestEnv) GitCommitWithShadowHooks(message string, files ...string) {
	env.T.Helper()

	// Stage files using go-git
	for _, file := range files {
		env.GitAdd(file)
	}

	// Create a temp file for the commit message
	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
		env.T.Fatalf("failed to write commit message file: %v", err)
	}

	// Run prepare-commit-msg hook
	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
	prepCmd.Dir = env.RepoDir
	prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=1")
	if output, err := prepCmd.CombinedOutput(); err != nil {
		env.T.Logf("prepare-commit-msg output: %s", output)
	}

	// Read the modified message
	modifiedMsg, err := os.ReadFile(msgFile)
	if err != nil {
		env.T.Fatalf("failed to read modified commit message: %v", err)
	}

	// Create the commit using go-git with the modified message
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
		Author: &object.Signature{
			Name:  "E2E Test User",
			Email: "e2e-test@example.com",
			When:  time.Now(),
		},
	})
	if err != nil {
		env.T.Fatalf("failed to commit: %v", err)
	}

	// Run post-commit hook
	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
	postCmd.Dir = env.RepoDir
	if output, err := postCmd.CombinedOutput(); err != nil {
		env.T.Logf("post-commit output: %s", output)
	}
}

// GitCheckoutNewBranch creates and checks out a new branch.
func (env *E2ETestEnv) GitCheckoutNewBranch(branchName string) {
	env.T.Helper()

	cmd := exec.Command("git", "checkout", "-b", branchName)
	cmd.Dir = env.RepoDir
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("failed to checkout new branch %s: %v\nOutput: %s", branchName, err, output)
	}
}

// GetHeadHash returns the current HEAD commit hash.
func (env *E2ETestEnv) GetHeadHash() string {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	head, err := repo.Head()
	if err != nil {
		env.T.Fatalf("failed to get HEAD: %v", err)
	}

	return head.Hash().String()
}

// RewindPoint mirrors the rewind --list JSON output.
type RewindPoint struct {
	ID               string    `json:"id"`
	Message          string    `json:"message"`
	MetadataDir      string    `json:"metadata_dir"`
	Date             time.Time `json:"date"`
	IsTaskCheckpoint bool      `json:"is_task_checkpoint"`
	ToolUseID        string    `json:"tool_use_id"`
	IsLogsOnly       bool      `json:"is_logs_only"`
	CondensationID   string    `json:"condensation_id"`
}

// GetRewindPoints returns available rewind points using the CLI.
func (env *E2ETestEnv) GetRewindPoints() []RewindPoint {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), "rewind", "--list")
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	if err != nil {
		env.T.Fatalf("rewind --list failed: %v\nOutput: %s", err, output)
	}

	// Parse JSON output
	var jsonPoints []struct {
		ID               string `json:"id"`
		Message          string `json:"message"`
		MetadataDir      string `json:"metadata_dir"`
		Date             string `json:"date"`
		IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
		ToolUseID        string `json:"tool_use_id"`
		IsLogsOnly       bool   `json:"is_logs_only"`
		CondensationID   string `json:"condensation_id"`
	}

	if err := json.Unmarshal(output, &jsonPoints); err != nil {
		env.T.Fatalf("failed to parse rewind points: %v\nOutput: %s", err, output)
	}

	points := make([]RewindPoint, len(jsonPoints))
	for i, jp := range jsonPoints {
		date, _ := time.Parse(time.RFC3339, jp.Date)
		points[i] = RewindPoint{
			ID:               jp.ID,
			Message:          jp.Message,
			MetadataDir:      jp.MetadataDir,
			Date:             date,
			IsTaskCheckpoint: jp.IsTaskCheckpoint,
			ToolUseID:        jp.ToolUseID,
			IsLogsOnly:       jp.IsLogsOnly,
			CondensationID:   jp.CondensationID,
		}
	}

	return points
}

// Rewind performs a rewind to the specified commit ID using the CLI.
func (env *E2ETestEnv) Rewind(commitID string) error {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), "rewind", "--to", commitID)
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	if err != nil {
		return errors.New("rewind failed: " + string(output))
	}

	env.T.Logf("Rewind output: %s", output)
	return nil
}

// BranchExists checks if a branch exists in the repository.
func (env *E2ETestEnv) BranchExists(branchName string) bool {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	refs, err := repo.References()
	if err != nil {
		env.T.Fatalf("failed to get references: %v", err)
	}

	found := false
	_ = refs.ForEach(func(ref *plumbing.Reference) error {
		if ref.Name().Short() == branchName {
			found = true
		}
		return nil
	})

	return found
}

// GetCommitMessage returns the commit message for the given commit hash.
func (env *E2ETestEnv) GetCommitMessage(hash string) string {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	commitHash := plumbing.NewHash(hash)
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		env.T.Fatalf("failed to get commit %s: %v", hash, err)
	}

	return commit.Message
}

// GetLatestCheckpointIDFromHistory walks backwards from HEAD and returns
// the checkpoint ID from the first commit with an Entire-Checkpoint trailer.
func (env *E2ETestEnv) GetLatestCheckpointIDFromHistory() string {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	head, err := repo.Head()
	if err != nil {
		env.T.Fatalf("failed to get HEAD: %v", err)
	}

	commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
	if err != nil {
		env.T.Fatalf("failed to iterate commits: %v", err)
	}

	var checkpointID string
	//nolint:errcheck
	commitIter.ForEach(func(c *object.Commit) error {
		// Look for Entire-Checkpoint trailer
		for _, line := range strings.Split(c.Message, "\n") {
			line = strings.TrimSpace(line)
			if strings.HasPrefix(line, "Entire-Checkpoint:") {
				checkpointID = strings.TrimSpace(strings.TrimPrefix(line, "Entire-Checkpoint:"))
				return errors.New("stop iteration")
			}
		}
		return nil
	})

	return checkpointID
}

// RunCLI runs the entire CLI with the given arguments and returns stdout.
func (env *E2ETestEnv) RunCLI(args ...string) string {
	env.T.Helper()
	output, err := env.RunCLIWithError(args...)
	if err != nil {
		env.T.Fatalf("CLI command failed: %v\nArgs: %v\nOutput: %s", err, args, output)
	}
	return output
}

// RunCLIWithError runs the entire CLI and returns output and error.
func (env *E2ETestEnv) RunCLIWithError(args ...string) (string, error) {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), args...)
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	return string(output), err
}

// RunAgent runs the agent with the given prompt and returns the result.
func (env *E2ETestEnv) RunAgent(prompt string) (*AgentResult, error) {
	env.T.Helper()
	return env.Agent.RunPrompt(context.Background(), env.RepoDir, prompt)
}

// RunAgentWithTools runs the agent with specific tools enabled.
func (env *E2ETestEnv) RunAgentWithTools(prompt string, tools []string) (*AgentResult, error) {
	env.T.Helper()
	return env.Agent.RunPromptWithTools(context.Background(), env.RepoDir, prompt, tools)
}

